    "founded_year": "2007",
    "city": "Baltimore",
    "state": "MD",
    "country": "USA",
    "record_label": "Agonia Records",
    "bio": "Formed in Baltimore, Maryland, in 2007, Visceral Disgorge is an elite and devastating American slamming brutal death metal band renowned for combining ultra-heavy, down-tuned slam grooves with lightning-fast blasting and inhuman vocal delivery. Built around founding members including vocalist Steve Rosenzweig, guitarist Charlie Park, and drummer Erik Malave, the group quickly became a towering pillar of modern extremity through their 2011 debut full-length, Ingesting Putridity, released via Comatose Music. Widely celebrated as a modern genre-defining masterpiece for its unrelenting heaviness and razor-sharp production, the album propelled the band onto major global festival stages. Following years of extensive international touring, Visceral Disgorge expanded their crushing sonic signature with their sophomore album, Sladest, in 2019 via Agonia Records, cementing their status as absolute royalty in contemporary underground death metal.",
